import Foundation

/// Migration 007 — the food log.
///
/// Appended; 001-006 are untouched.
///
/// The reference database answers "what is in this food". Nothing recorded
/// "the user ate 150 g of it". That is this table.
///
/// Two decisions worth the words:
///
/// 1. **`food_ref` is text, with no foreign key.** It holds a
///    `SourceIdentifier` — `usda:1105904`, `almanac:dish-kabsa`. Processing
///    Design v0.1 §3 keeps "remove a whole source" a one-line delete when a
///    rights holder says no; a foreign key with ON DELETE CASCADE would turn
///    that delete into the erasure of the user's own meal history. The log is
///    the user's record, not the publisher's, and it outlives the reference
///    rows it points at. `food_name_text` is what keeps an orphaned row
///    readable — the same reversibility discipline as
///    `NutrientValue.sourceValue` and `lab_observation.source_analyte_text`.
=== ponytail Migration008 ===
import Foundation

/// Migration 008 — the nutrition reference tables, portions, and native dishes.
///
/// Appended; 001-007 are untouched.
///
/// **Reconciliation note.** The 2026-09-14 handoff describes `nutrition_food`
/// and `nutrition_value` as already existing on an unpushed branch
/// (`codex/manual-entry`, `9445a51`). They are not in this tree, and portions
/// and dish entry cannot be built without them, so they are authored here. When
/// that branch lands, one of the two definitions wins and the other's importer
/// is repointed — a mechanical merge, but a real one. Nothing below invents a
/// column the pipeline does not already produce: the shapes follow USDA
/// `food_portion` and the CoFID `1.2 Factors` sheet as Processing Design v0.1
/// §4 describes them.
///
/// Three things worth stating about the shape:
///
/// 1. **Values are per 100 g of edible portion**, which is what every source in
///    groups A and B publishes. `edible_proportion` is the separate CoFID fact
///    that converts an as-purchased weight into that edible weight; it is not a
///    nutrient and does not belong in `nutrition_value`.
/// 2. **Specific gravity is stored as a portion of 1 ml**, not as its own
///    column. A volume-to-mass factor and a household measure answer the same
///    question — "how many grams is this much of it" — so one lookup serves
///    both and `2 cups` and `250 ml` resolve through the same path.
/// 3. **Portions are not unique per (food, unit).** USDA genuinely carries
///    several, and `lab_catalog_alias` already established what this codebase
///    does about that: return the candidates and refuse to pick. A `LIMIT 1`
///    here would silently choose a gram weight, which is the defect
///    `testAliasCollisionAfterSeedingLeavesTheRecordUnmatched` exists to
///    prevent, applied to mass.
public enum Migration008_NutritionReference: Migration {
    public static let version = 8
    public static let name = "nutrition_reference"

    public static func up(_ db: Database) throws {
        try db.execute("""
        CREATE TABLE nutrition_food (
            food_ref          TEXT    PRIMARY KEY,
            name_text         TEXT    NOT NULL,
            name_fold         TEXT    NOT NULL,
            licence_group     TEXT    NOT NULL,
            -- CoFID '1.2 Factors': the fraction of the as-purchased weight that
            -- is edible. Nil means the source did not state one, which is not
            -- the same as 1.0 and must not be rounded up to it.
            edible_proportion REAL,
            -- Dishes only: the finished weight when it differs from the sum of
            -- the components, because cooking loses water. Nil means the sum.
            yield_grams       REAL,
            source_value      TEXT,
            created_at        TEXT    NOT NULL,
            updated_at        TEXT    NOT NULL
        );
        """)
        try db.execute("CREATE INDEX idx_nutrition_food_fold ON nutrition_food (name_fold);")

        try db.execute("""
        CREATE TABLE nutrition_value (
            food_ref           TEXT    NOT NULL
                                   REFERENCES nutrition_food(food_ref) ON DELETE CASCADE,
            nutrient_id        TEXT    NOT NULL,
            -- Per 100 g edible portion. Nullable: `qualifier` carries the three
            -- facts a Double collapses into one — reported zero, trace,
            -- unmeasured. See NutrientQualifier.
            amount             REAL,
            qualifier          TEXT    NOT NULL,
            confidence         TEXT,
            -- The original cell. Whatever the parser gets wrong, the value is
            -- re-derivable without going back to raw/.
            source_value       TEXT    NOT NULL,
            source_nutrient_id TEXT    NOT NULL,
            source_unit        TEXT    NOT NULL,
            licence_group      TEXT    NOT NULL,
            PRIMARY KEY (food_ref, nutrient_id)
        );
        """)

        try db.execute("""
        CREATE TABLE nutrition_portion (
            id            TEXT    PRIMARY KEY,
            food_ref      TEXT    NOT NULL
                              REFERENCES nutrition_food(food_ref) ON DELETE CASCADE,
            amount        REAL    NOT NULL,
            unit_text     TEXT    NOT NULL,
            unit_fold     TEXT    NOT NULL,
            modifier_text TEXT,
            gram_weight   REAL    NOT NULL,
            sequence      INTEGER NOT NULL DEFAULT 0,
            licence_group TEXT    NOT NULL,
=== ponytail Migration009 ===
import Foundation

/// Migration 009 — a portion is not duplicated by re-importing it.
///
/// Appended; 001-008 are untouched, on the rule this repository already
/// follows that a committed migration is treated the same as an applied one.
///
/// **The defect.** `nutrition_portion` carried no uniqueness at all, so calling
/// `addPortion` twice with the same row — which is what re-running an importer
/// does — stored it twice. Two identical "1 cup" rows are then reported as
/// `PortionMatch.ambiguous`, and `grams(of:amount:unit:)` returns nil rather
/// than 158. A phantom disagreement between a row and itself, presented to the
/// user as a measure that cannot be resolved.
///
/// The key is everything that makes two measures genuinely different: the food,
/// the folded unit, the modifier, the stated amount and the gram weight. USDA
/// really does carry several "1 cup" rows per food with different weights, and
/// those must still coexist — this rejects only a row identical to one already
/// held. `COALESCE(modifier_text, '')` is not decoration: SQLite treats NULLs
/// as distinct in a unique index, so without it the unmodified rows — the
/// common case — would go on duplicating.
public enum Migration009_PortionIdentity: Migration {
    public static let version = 9
    public static let name = "portion_identity"

    public static func up(_ db: Database) throws {
        // Any duplicate already stored is collapsed before the index is built,
        // keeping the first by id so the choice is not row order.
        try db.execute("""
        DELETE FROM nutrition_portion WHERE id NOT IN (
            SELECT MIN(id) FROM nutrition_portion
            GROUP BY food_ref, unit_fold, COALESCE(modifier_text, ''), amount, gram_weight
        );
        """)
        try db.execute("""
        CREATE UNIQUE INDEX idx_nutrition_portion_identity
            ON nutrition_portion (food_ref, unit_fold, COALESCE(modifier_text, ''),
                                  amount, gram_weight);
        """)
    }

