1	import Foundation
2	import CSQLite
3	
4	/// Bound value for a prepared statement parameter.
5	public enum SQLValue: Sendable, Hashable {
6	    case null
7	    case integer(Int64)
8	    case real(Double)
9	    case text(String)
10	    case blob([UInt8])
11	}
12	
13	/// A single row, addressable by column name.
14	public struct Row: Sendable {
15	    private let values: [String: SQLValue]
16	    init(_ values: [String: SQLValue]) { self.values = values }
17	
18	    public subscript(column: String) -> SQLValue? { values[column] }
19	
20	    public func int(_ column: String) -> Int64? {
21	        if case .integer(let v)? = values[column] { return v }
22	        return nil
23	    }
24	    public func double(_ column: String) -> Double? {
25	        switch values[column] {
26	        case .real(let v)?: return v
27	        case .integer(let v)?: return Double(v)
28	        default: return nil
29	        }
30	    }
31	    public func string(_ column: String) -> String? {
32	        if case .text(let v)? = values[column] { return v }
33	        return nil
34	    }
35	    public func isNull(_ column: String) -> Bool {
36	        if case .null? = values[column] { return true }
37	        return values[column] == nil
38	    }
39	}
40	
41	private let SQLITE_TRANSIENT = unsafeBitCast(-1, to: sqlite3_destructor_type.self)
42	
43	/// A thin, non-generic wrapper over the SQLite C API.
44	///
45	/// Deliberately small. It is a seam, not an ORM: the schema lives in
46	/// migrations, and everything above this type works in plain SQL so that a
47	/// migration and a query read the same on Linux and on iOS.
48	/// Thread safety: the connection is opened with SQLITE_OPEN_FULLMUTEX, so
49	/// SQLite itself serialises concurrent use of the handle. That is what makes
50	/// the `@unchecked Sendable` claim true rather than convenient.
51	public final class Database: @unchecked Sendable {
52	    private var handle: OpaquePointer?
53	    /// Internal escape hatch for C APIs that need the raw connection.
54	    var rawHandle: OpaquePointer? { handle }
55	    public let path: String
56	
57	    public init(path: String) throws {
58	        self.path = path
59	        var h: OpaquePointer?
60	        let flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX
61	        let rc = sqlite3_open_v2(path, &h, flags, nil)
62	        guard rc == SQLITE_OK, let opened = h else {
63	            let err = SQLiteError.from(h, code: rc)
64	            if h != nil { sqlite3_close_v2(h) }
65	            throw err
66	        }
67	        self.handle = opened
68	        try execute("PRAGMA foreign_keys = ON;")
69	        try execute("PRAGMA journal_mode = WAL;")
70	        try execute("PRAGMA busy_timeout = 5000;")
71	    }
72	
73	    public static func inMemory() throws -> Database { try Database(path: ":memory:") }
74	
75	    deinit { if let handle { sqlite3_close_v2(handle) } }
76	
77	    /// Runs one or more statements with no parameters and no result rows.
78	    public func execute(_ sql: String) throws {
79	        var errmsg: UnsafeMutablePointer<CChar>?
80	        let rc = sqlite3_exec(handle, sql, nil, nil, &errmsg)
81	        if rc != SQLITE_OK {
82	            let message = errmsg.map { String(cString: $0) } ?? "unknown sqlite error"
83	            if let errmsg { sqlite3_free(errmsg) }
84	            throw SQLiteError(code: rc, message: message, sql: sql)
85	        }
86	    }
87	
88	    @discardableResult
89	    public func run(_ sql: String, _ parameters: [SQLValue] = []) throws -> Int {
90	        let stmt = try prepare(sql, parameters)
91	        defer { sqlite3_finalize(stmt) }
92	        let rc = sqlite3_step(stmt)
93	        guard rc == SQLITE_DONE || rc == SQLITE_ROW else {
94	            throw SQLiteError.from(handle, code: rc, sql: sql)
95	        }
96	        return Int(sqlite3_changes(handle))
97	    }
98	
99	    public func query(_ sql: String, _ parameters: [SQLValue] = []) throws -> [Row] {
100	        let stmt = try prepare(sql, parameters)
101	        defer { sqlite3_finalize(stmt) }
102	
103	        let columnCount = Int(sqlite3_column_count(stmt))
104	        var names: [String] = []
105	        names.reserveCapacity(columnCount)
106	        for i in 0..<columnCount {
107	            names.append(String(cString: sqlite3_column_name(stmt, Int32(i))))
108	        }
109	
110	        var rows: [Row] = []
111	        while true {
112	            let rc = sqlite3_step(stmt)
113	            if rc == SQLITE_DONE { break }
114	            guard rc == SQLITE_ROW else { throw SQLiteError.from(handle, code: rc, sql: sql) }
115	            var values: [String: SQLValue] = [:]
116	            for i in 0..<columnCount {
117	                values[names[i]] = columnValue(stmt, Int32(i))
118	            }
119	            rows.append(Row(values))
120	        }
121	        return rows
122	    }
123	
124	    private func columnValue(_ stmt: OpaquePointer?, _ index: Int32) -> SQLValue {
125	        switch sqlite3_column_type(stmt, index) {
126	        case SQLITE_INTEGER: return .integer(sqlite3_column_int64(stmt, index))
127	        case SQLITE_FLOAT:   return .real(sqlite3_column_double(stmt, index))
128	        case SQLITE_TEXT:
129	            guard let c = sqlite3_column_text(stmt, index) else { return .null }
130	            return .text(String(cString: c))
131	        case SQLITE_BLOB:
132	            let n = Int(sqlite3_column_bytes(stmt, index))
133	            guard n > 0, let p = sqlite3_column_blob(stmt, index) else { return .blob([]) }
134	            let buf = UnsafeRawBufferPointer(start: p, count: n)
135	            return .blob(Array(buf))
136	        default: return .null
137	        }
138	    }
139	
140	    private func prepare(_ sql: String, _ parameters: [SQLValue]) throws -> OpaquePointer? {
141	        var stmt: OpaquePointer?
142	        let rc = sqlite3_prepare_v2(handle, sql, -1, &stmt, nil)
143	        guard rc == SQLITE_OK else { throw SQLiteError.from(handle, code: rc, sql: sql) }
144	        for (offset, value) in parameters.enumerated() {
145	            let i = Int32(offset + 1)
146	            let brc: Int32
147	            switch value {
148	            case .null:            brc = sqlite3_bind_null(stmt, i)
149	            case .integer(let v):  brc = sqlite3_bind_int64(stmt, i, v)
150	            case .real(let v):     brc = sqlite3_bind_double(stmt, i, v)
151	            case .text(let v):     brc = sqlite3_bind_text(stmt, i, v, -1, SQLITE_TRANSIENT)
152	            case .blob(let bytes):
153	                brc = bytes.isEmpty
154	                    ? sqlite3_bind_zeroblob(stmt, i, 0)
155	                    : bytes.withUnsafeBufferPointer {
156	                        sqlite3_bind_blob(stmt, i, $0.baseAddress, Int32(bytes.count), SQLITE_TRANSIENT)
157	                      }
158	            }
159	            guard brc == SQLITE_OK else {
160	                sqlite3_finalize(stmt)
161	                throw SQLiteError.from(handle, code: brc, sql: sql)
162	            }
163	        }
164	        return stmt
165	    }
166	
167	    /// Runs `body` inside a transaction, rolling back on any thrown error.
168	    public func transaction<T>(_ body: () throws -> T) throws -> T {
169	        try execute("BEGIN IMMEDIATE;")
170	        do {
171	            let result = try body()
