import Foundation

/// A reference food as its publisher identifies and names it.
public struct NutritionFood: Sendable, Hashable {
    public let ref: SourceIdentifier
    public let licenceGroup: LicenceGroup
    public let foodGroupCode: String
    public let foodGroupName: String
    /// Where the row came from in the publisher's file, for tracing a value back.
    public let sourceRecord: String
    /// ISO 639 language code -> name.
    public let names: [String: String]
    public let primaryName: String
}

/// Read access to the imported reference foods. A seam over SQL, not an ORM.
public struct NutritionCatalog: @unchecked Sendable {
    private let db: Database

    public init(db: Database) {
        self.db = db
    }

    public func food(_ ref: SourceIdentifier) throws -> NutritionFood? {
        guard let row = try db.query("""
            SELECT licence_group, food_group_code, food_group_name, source_record
            FROM nutrition_food WHERE food_ref = ?;
            """, [.text(ref.description)]).first,
              let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:)) else { return nil }
        var names: [String: String] = [:]
        var primary = ""
        for name in try db.query("""
            SELECT language, name, is_primary FROM nutrition_food_name WHERE food_ref = ? ORDER BY language;
            """, [.text(ref.description)]) {
            guard let language = name.string("language"), let text = name.string("name") else { continue }
            names[language] = text
            if name.int("is_primary") == 1 { primary = text }
        }
        return NutritionFood(ref: ref, licenceGroup: group, foodGroupCode: row.string("food_group_code") ?? "",
                             foodGroupName: row.string("food_group_name") ?? "",
                             sourceRecord: row.string("source_record") ?? "", names: names, primaryName: primary)
    }

    /// Every value published for the food on one basis. Tokens keep an empty amount.
    public func values(for ref: SourceIdentifier, basis: NutritionBasis) throws -> [NutrientValue] {
        try db.query("""
            SELECT nutrient_id, amount, qualifier, confidence, source_value, source_nutrient_id, source_unit,
                   licence_group
            FROM nutrition_value WHERE food_ref = ? AND basis = ? ORDER BY nutrient_id;
            """, [.text(ref.description), .text(basis.rawValue)]).compactMap { row in
            // The table's CHECK constraints admit only values these types can parse.
            guard let nutrient = row.string("nutrient_id"),
                  let qualifier = row.string("qualifier").flatMap(NutrientQualifier.init(rawValue:)),
                  let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:)),
                  let sourceValue = row.string("source_value"),
                  let sourceNutrient = row.string("source_nutrient_id"),
                  let sourceUnit = row.string("source_unit") else { return nil }
            return NutrientValue(foodRef: ref, nutrientID: nutrient, amount: row.double("amount"),
                                 qualifier: qualifier, confidence: row.string("confidence"),
                                 sourceValue: sourceValue, sourceNutrientID: sourceNutrient,
                                 sourceUnit: sourceUnit, licenceGroup: group, basis: basis)
        }
    }

    /// The bases the publisher gives values on: per 100 g, and for some liquids per 100 mL too.
    public func bases(for ref: SourceIdentifier) throws -> [NutritionBasis] {
        try db.query("SELECT DISTINCT basis FROM nutrition_value WHERE food_ref = ? ORDER BY basis;",
                     [.text(ref.description)])
            .compactMap { $0.string("basis").flatMap(NutritionBasis.init(rawValue:)) }
    }

    /// Almanac's calorie number for the food on one basis (see `EnergyEstimate.preferred`).
    public func energy(for ref: SourceIdentifier, basis: NutritionBasis) throws -> EnergyEstimate? {
        EnergyEstimate.preferred(from: try values(for: ref, basis: basis), basis: basis)
    }

    /// Foods whose name in any language contains `text`, compared folded (`TextFold`):
    /// case, accents and Arabic letter variants do not matter. Each food once, by primary name.
    public func search(_ text: String, limit: Int = 50) throws -> [NutritionFood] {
        let folded = TextFold.fold(text)
        guard !folded.isEmpty, limit > 0 else { return [] }
        let pattern = "%" + folded.replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "%", with: "\\%")
            .replacingOccurrences(of: "_", with: "\\_") + "%"
        return try db.query("""
            SELECT f.food_ref FROM nutrition_food f
            JOIN nutrition_food_name p ON p.food_ref = f.food_ref AND p.is_primary = 1
            WHERE EXISTS (SELECT 1 FROM nutrition_food_name n
                          WHERE n.food_ref = f.food_ref AND n.name_fold LIKE ? ESCAPE '\\')
            ORDER BY p.name_fold, f.food_ref
            LIMIT ?;
            """, [.text(pattern), .integer(Int64(limit))])
            .compactMap { row in
                try row.string("food_ref").flatMap(SourceIdentifier.init(parsing:)).flatMap(food)
            }
    }
}

import Foundation

// MARK: - Values

public enum NutritionError: Error, CustomStringConvertible, Sendable {
    case foodNotFound(SourceIdentifier)
    case invalidGramWeight(Double)
    case invalidAmount(Double)
    case notANativeFood(SourceIdentifier)
    case recipeCycle(SourceIdentifier)
    case notARemovableSource(SourceIdentifier.Namespace)
    case dishHasNoRecipe(SourceIdentifier)

    public var description: String {
        switch self {
        case .foodNotFound(let ref):
            return "no food '\(ref)' in the nutrition catalog."
        case .invalidGramWeight(let g):
            return "a portion's gram weight must be finite and greater than zero; got \(g)."
        case .invalidAmount(let a):
            return "a measure's amount must be finite and greater than zero; got \(a)."
        case .notANativeFood(let ref):
            return "'\(ref)' is published by \(ref.namespace.rawValue); only 'almanac:' foods "
                 + "may be authored here. A publisher's row is corrected upstream, not edited."
        case .recipeCycle(let ref):
            return "'\(ref)' would end up an ingredient of itself, directly or through "
                 + "another dish. The reduction would then compute each from the other's "
                 + "previous answer and report a number with nothing behind it."
        case .dishHasNoRecipe(let ref):
            return "'\(ref)' has no recipe to recompute from. Its values were entered "
                 + "directly, and reducing an empty ingredient list would replace them "
                 + "with nothing."
        case .notARemovableSource(let namespace):
            return "'\(namespace.rawValue)' is Almanac's own namespace. Removing a source is "
                 + "for a publisher withdrawing its data; it is not a way to delete the "
                 + "dishes a person wrote."
        }
    }
}

/// A food in the reference catalog, identified by its publisher's id.
public struct NutritionFood: Sendable, Hashable {
    public let ref: SourceIdentifier
    public let nameText: String
    public let licenceGroup: LicenceGroup
    /// CoFID `1.2 Factors`: the fraction of an as-purchased weight that is
    /// edible. Nil where the source did not state one — not 1.0.
    public let edibleProportion: Double?
    /// Dishes only: the finished weight, when cooking makes it differ from the
    /// sum of the components. Nil means the sum.
    public let yieldGrams: Double?
    public let sourceValue: String?

    public init(ref: SourceIdentifier, nameText: String, licenceGroup: LicenceGroup,
                edibleProportion: Double? = nil, yieldGrams: Double? = nil,
                sourceValue: String? = nil) {
        self.ref = ref
        self.nameText = nameText
        self.licenceGroup = licenceGroup
        self.edibleProportion = edibleProportion
        self.yieldGrams = yieldGrams
        self.sourceValue = sourceValue
    }
}

/// One household measure, or one volume-to-mass factor.
///
/// USDA `food_portion` is the shape: an amount, a unit, an optional modifier
/// and the gram weight the publisher measured. A specific gravity is the same
/// fact written `1 ml → 1.03 g`, which is why it needs no separate table.
public struct NutritionPortion: Sendable, Hashable {
    public let id: String
    public let foodRef: SourceIdentifier
    public let amount: Double
    public let unitText: String
    public let modifierText: String?
    public let gramWeight: Double
    public let sequence: Int
    public let licenceGroup: LicenceGroup
    public let sourceValue: String?

    public init(foodRef: SourceIdentifier, amount: Double, unitText: String,
                gramWeight: Double, modifierText: String? = nil, sequence: Int = 0,
                licenceGroup: LicenceGroup = .permissive, sourceValue: String? = nil,
                id: String = UUID().uuidString) {
        self.id = id
        self.foodRef = foodRef
        self.amount = amount
        self.unitText = unitText
        self.modifierText = modifierText
        self.gramWeight = gramWeight
        self.sequence = sequence
        self.licenceGroup = licenceGroup
        self.sourceValue = sourceValue
    }

    /// Grams per one of `unitText`. The stored row may be "2 tbsp = 30 g".
    public var gramsPerUnit: Double { gramWeight / amount }
}

/// The result of asking what a measure weighs.
///
/// `ambiguous` is a real answer, not a failure to find one: USDA carries
/// several "1 cup" rows for the same food, and picking by row order would
/// silently choose a mass. Same discipline as `CatalogMatchResult`.
public enum PortionMatch: Sendable, Hashable {
    /// Deliberately not spelled `none`: this enum is returned unwrapped, and a
    /// case by that name reads as `Optional.none` at every call site.
    case notFound
    case one(NutritionPortion)
    case ambiguous([NutritionPortion])

    public var resolved: NutritionPortion? {
        if case .one(let p) = self { return p }
        return nil
    }
}

// MARK: - Store

/// Read and write access to the nutrition reference tables.
///
/// Writes re-assert the licence guard. Processing Design v0.1 §5: a group C or
/// D row reaching a user's database is the failure this is here to make loud,
/// and filtering it silently would hide the same bug.
public struct NutritionCatalog: Sendable {
    private let db: Database
    private let clock: any Clock

    public init(db: Database, clock: any Clock = SystemClock()) {
        self.db = db
        self.clock = clock
    }

    private var nowText: String { ISO8601DateFormatter().string(from: clock.now) }

    // MARK: Foods

    @discardableResult
    public func upsert(_ food: NutritionFood) throws -> SourceIdentifier {
        try BundleGuard.assertShippable([(identifier: food.ref.description,
                                          group: food.licenceGroup)])
        try db.run("""
        INSERT INTO nutrition_food
            (food_ref, name_text, name_fold, licence_group, edible_proportion,
             yield_grams, source_value, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(food_ref) DO UPDATE SET
            name_text         = excluded.name_text,
            name_fold         = excluded.name_fold,
            licence_group     = excluded.licence_group,
            edible_proportion = excluded.edible_proportion,
            yield_grams       = excluded.yield_grams,
            source_value      = excluded.source_value,
            updated_at        = excluded.updated_at;
        """, [
            .text(food.ref.description), .text(food.nameText),
            .text(TextFold.fold(food.nameText)), .text(food.licenceGroup.rawValue),
            food.edibleProportion.map { SQLValue.real($0) } ?? .null,
            food.yieldGrams.map { SQLValue.real($0) } ?? .null,
            food.sourceValue.map { SQLValue.text($0) } ?? .null,
            .text(nowText), .text(nowText)
        ])
        return food.ref
    }

    public func food(_ ref: SourceIdentifier) throws -> NutritionFood? {
        try db.query("""
            SELECT food_ref, name_text, licence_group, edible_proportion, yield_grams, source_value
            FROM nutrition_food WHERE food_ref = ?;
            """, [.text(ref.description)]).first.flatMap(NutritionCatalog.food(from:))
    }

    /// Name search, folded across case, diacritics and script by `TextFold` —
    /// the same folding Laboratory's alias lookup uses, so "بصل" and "Basal"
    /// behave the same way here as there.
    public func search(_ text: String, limit: Int = 20) throws -> [NutritionFood] {
        let fold = TextFold.fold(text)
        guard !fold.isEmpty else { return [] }
        return try db.query("""
            SELECT food_ref, name_text, licence_group, edible_proportion, yield_grams, source_value
            FROM nutrition_food WHERE name_fold LIKE ? ESCAPE '\\'
            ORDER BY LENGTH(name_fold), name_fold LIMIT ?;
            """, [.text("%\(NutritionCatalog.escapingWildcards(fold))%"),
                  .integer(Int64(limit))])
            .compactMap(NutritionCatalog.food(from:))
    }

    /// `%` and `_` in a search term are characters the user typed, not wildcards.
    static func escapingWildcards(_ text: String) -> String {
        text.replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "%", with: "\\%")
            .replacingOccurrences(of: "_", with: "\\_")
    }

    static func food(from row: Row) -> NutritionFood? {
        guard let ref = row.string("food_ref").flatMap(SourceIdentifier.init(parsing:)),
              let name = row.string("name_text"),
              let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:))
        else { return nil }
        return NutritionFood(ref: ref, nameText: name, licenceGroup: group,
                             edibleProportion: row.double("edible_proportion"),
                             yieldGrams: row.double("yield_grams"),
                             sourceValue: row.string("source_value"))
    }

    /// Removes every row a publisher contributed: its foods, their values and
    /// their portions.
    ///
    /// `SourceIdentifier` namespaces exist so that this is one delete when a
    /// rights holder says no. Until now that was a claim in a comment with no
    /// code behind it. Returns how many foods went.
    ///
    /// What deliberately survives: the user's food log entries, which keep the
    /// name they were logged under and are reported by `NutritionTotals` as
    /// `mealsWithoutReference`; and any `almanac:` dish built on the removed
    /// rows, whose recipe is kept and whose reduction now reports
    /// `missingComponents`. A withdrawal by a publisher is a fact about the
    /// publisher, not permission to erase what the person recorded eating.
    @discardableResult
    public func removeSource(_ namespace: SourceIdentifier.Namespace) throws -> Int {
        // Almanac's own rows are not a third party's to withdraw, and this call
        // would silently delete every dish the person wrote.
        guard namespace != .almanac else {
            throw NutritionError.notARemovableSource(namespace)
        }
        // Safe as a LIKE pattern because Namespace is a closed enum and no raw
        // value contains `%` or `_`. A namespace that did would need escaping,
        // as `search` does for text a person typed.
        return try db.run("DELETE FROM nutrition_food WHERE food_ref LIKE ?;",
                          [.text("\(namespace.rawValue):%")])
    }

    // MARK: Values

    public func setValues(_ values: [NutrientValue], for ref: SourceIdentifier,
                          replacingAll: Bool = true) throws {
        let rows: [(identifier: String, group: LicenceGroup)] = values.map {
            (identifier: "\($0.foodRef):\($0.nutrientID)", group: $0.licenceGroup)
        }
        try BundleGuard.assertShippable(rows)
        guard try food(ref) != nil else { throw NutritionError.foodNotFound(ref) }
        try db.transaction {
            if replacingAll {
                try db.run("DELETE FROM nutrition_value WHERE food_ref = ?;",
                           [.text(ref.description)])
            }
            for value in values {
                try db.run("""
                INSERT INTO nutrition_value
                    (food_ref, nutrient_id, amount, qualifier, confidence,
                     source_value, source_nutrient_id, source_unit, licence_group)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(food_ref, nutrient_id) DO UPDATE SET
                    amount             = excluded.amount,
                    qualifier          = excluded.qualifier,
                    confidence         = excluded.confidence,
                    source_value       = excluded.source_value,
                    source_nutrient_id = excluded.source_nutrient_id,
                    source_unit        = excluded.source_unit,
                    licence_group      = excluded.licence_group;
                """, [
                    .text(ref.description), .text(value.nutrientID),
                    value.amount.map { SQLValue.real($0) } ?? .null,
                    .text(value.qualifier.rawValue),
                    value.confidence.map { SQLValue.text($0) } ?? .null,
                    .text(value.sourceValue), .text(value.sourceNutrientID),
                    .text(value.sourceUnit), .text(value.licenceGroup.rawValue)
                ])
            }
        }
    }

    /// Per 100 g of edible portion, as every group A and B source publishes it.
    public func values(of ref: SourceIdentifier) throws -> [NutrientValue] {
        try db.query("""
            SELECT nutrient_id, amount, qualifier, confidence, source_value,
                   source_nutrient_id, source_unit, licence_group
            FROM nutrition_value WHERE food_ref = ? ORDER BY nutrient_id;
            """, [.text(ref.description)]).compactMap { row in
            guard let nutrientID = row.string("nutrient_id"),
                  let qualifier = row.string("qualifier")
                      .flatMap(NutrientQualifier.init(rawValue:)),
                  let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:))
            else { return nil }
            return NutrientValue(
                foodRef: ref, nutrientID: nutrientID, amount: row.double("amount"),
                qualifier: qualifier, confidence: row.string("confidence"),
                sourceValue: row.string("source_value") ?? "",
                sourceNutrientID: row.string("source_nutrient_id") ?? "",
                sourceUnit: row.string("source_unit") ?? "", licenceGroup: group)
        }
    }

    public func value(of ref: SourceIdentifier, nutrientID: String) throws -> NutrientValue? {
        try values(of: ref).first { $0.nutrientID == nutrientID }
    }

    // MARK: Portions

    @discardableResult
    public func addPortion(_ portion: NutritionPortion) throws -> String {
        guard portion.gramWeight.isFinite, portion.gramWeight > 0 else {
            throw NutritionError.invalidGramWeight(portion.gramWeight)
        }
        guard portion.amount.isFinite, portion.amount > 0 else {
            throw NutritionError.invalidAmount(portion.amount)
        }
        try BundleGuard.assertShippable([(identifier: portion.foodRef.description,
                                          group: portion.licenceGroup)])
        guard try food(portion.foodRef) != nil else {
            throw NutritionError.foodNotFound(portion.foodRef)
        }
        // Re-importing a measure already held updates it rather than storing a
        // second copy — two identical rows would otherwise read as an ambiguity
        // between a row and itself. See Migration009.
        try db.run("""
        INSERT INTO nutrition_portion
            (id, food_ref, amount, unit_text, unit_fold, modifier_text,
             gram_weight, sequence, licence_group, source_value)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(food_ref, unit_fold, COALESCE(modifier_text, ''), amount, gram_weight)
        DO UPDATE SET
            unit_text     = excluded.unit_text,
            sequence      = excluded.sequence,
            licence_group = excluded.licence_group,
            source_value  = excluded.source_value;
        """, [
            .text(portion.id), .text(portion.foodRef.description), .real(portion.amount),
            .text(portion.unitText), .text(TextFold.fold(portion.unitText)),
            portion.modifierText.map { SQLValue.text($0) } ?? .null,
            .real(portion.gramWeight), .integer(Int64(portion.sequence)),
            .text(portion.licenceGroup.rawValue),
            portion.sourceValue.map { SQLValue.text($0) } ?? .null
        ])
        // The held row's id, which is the caller's only when this was an insert.
        return try db.query("""
            SELECT id FROM nutrition_portion
            WHERE food_ref = ? AND unit_fold = ? AND COALESCE(modifier_text, '') = ?
              AND amount = ? AND gram_weight = ?;
            """, [.text(portion.foodRef.description), .text(TextFold.fold(portion.unitText)),
                  .text(portion.modifierText ?? ""), .real(portion.amount),
                  .real(portion.gramWeight)]).first?.string("id") ?? portion.id
    }

    /// Every measure held for a food, in the publisher's own order.
    public func portions(of ref: SourceIdentifier) throws -> [NutritionPortion] {
        try db.query("""
            SELECT id, food_ref, amount, unit_text, modifier_text, gram_weight,
                   sequence, licence_group, source_value
            FROM nutrition_portion WHERE food_ref = ? ORDER BY sequence, unit_text;
            """, [.text(ref.description)]).compactMap(NutritionCatalog.portion(from:))
    }

    /// What one named measure of this food weighs.
    ///
    /// A `modifier` narrows the search — "1 cup, cooked" against "1 cup, raw".
    /// When several rows still match, they all come back: choosing between two
    /// gram weights is the caller's decision with the user in front of it, not
    /// a silent pick by row order.
    public func portion(of ref: SourceIdentifier, unit: String,
                        modifier: String? = nil) throws -> PortionMatch {
        let forms = NutritionCatalog.matchableForms(unit)
        guard !forms.isEmpty else { return .notFound }
        var candidates = try db.query("""
            SELECT id, food_ref, amount, unit_text, modifier_text, gram_weight,
                   sequence, licence_group, source_value
            FROM nutrition_portion
            WHERE food_ref = ? AND unit_fold IN (?, ?, ?)
            ORDER BY sequence, id;
            """, [.text(ref.description), .text(forms[0]), .text(forms[1]), .text(forms[2])])
            .compactMap(NutritionCatalog.portion(from:))

        if let modifier {
            let wanted = TextFold.fold(modifier)
            let narrowed = candidates.filter {
                TextFold.fold($0.modifierText ?? "") == wanted
            }
            // An unmatched modifier narrows to nothing rather than falling back
            // to every row: "1 cup, cooked" must not quietly answer with raw.
            candidates = narrowed
        }

        switch candidates.count {
        case 0:  return .notFound
        case 1:  return .one(candidates[0])
        default: return .ambiguous(candidates)
        }
    }

    /// Resolves a household measure to grams — "2 cups" → 316 g.
    ///
    /// Nil when the measure is unknown or ambiguous. The caller stores the
    /// number; it is deliberately not recomputed at read time, because a later
    /// correction to a gram weight must not silently change the mass of a meal
    /// the user already confirmed.
    public func grams(of ref: SourceIdentifier, amount: Double, unit: String,
                      modifier: String? = nil) throws -> Double? {
        guard amount.isFinite, amount > 0 else { throw NutritionError.invalidAmount(amount) }
        guard let portion = try self.portion(of: ref, unit: unit, modifier: modifier).resolved
        else { return nil }
        return portion.gramsPerUnit * amount
    }

    /// The edible weight of an as-purchased weight — a banana with its skin.
    ///
    /// Nil where the source stated no edible proportion. Returning the input
    /// unchanged would assert that all of it is edible, which is exactly the
    /// claim a missing factor does not make.
    public func edibleGrams(of ref: SourceIdentifier, asPurchased grams: Double) throws -> Double? {
        guard let proportion = try food(ref)?.edibleProportion else { return nil }
        return grams * proportion
    }

    /// The folded forms a typed measure may match: itself, its plural, and its
    /// singular. Always three, so the query shape is fixed.
    ///
    /// `TextFold` normalises case, diacritics and script — not grammar — so a
    /// stored "cup" never matched a typed "cups", and "2 cups" is exactly the
    /// input this feature exists to answer. Matching extra forms at *query*
    /// time rather than normalising what is stored means nothing is lost on
    /// the way in and two genuinely different units are never merged: a
    /// publisher shipping both "cup" and "cups" rows still comes back
    /// `.ambiguous`, which is the honest answer.
    ///
    /// ponytail: English -s only. "glasses"/"glass" and other -es plurals miss
    /// and fall out as `.notFound`, which the caller already handles. A unit
    /// dictionary is the upgrade if a source ships measures this gets wrong.
    static func matchableForms(_ unit: String) -> [String] {
        let fold = TextFold.fold(unit)
        guard !fold.isEmpty else { return [] }
        let singular = fold.count > 2 && fold.hasSuffix("s") ? String(fold.dropLast()) : fold
        return [fold, fold + "s", singular]
    }

    private static func portion(from row: Row) -> NutritionPortion? {
        guard let id = row.string("id"),
              let ref = row.string("food_ref").flatMap(SourceIdentifier.init(parsing:)),
              let amount = row.double("amount"), let unit = row.string("unit_text"),
              let gramWeight = row.double("gram_weight"),
              let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:))
        else { return nil }
        return NutritionPortion(
            foodRef: ref, amount: amount, unitText: unit, gramWeight: gramWeight,
            modifierText: row.string("modifier_text"),
            sequence: Int(row.int("sequence") ?? 0), licenceGroup: group,
            sourceValue: row.string("source_value"), id: id)
    }
}

import Foundation

/// Canonical nutrient ids this module reasons about by name.
///
/// Deliberately not the whole nutrient dictionary. These are the six the energy
/// calculation and the dish reduction need to *name*; every other nutrient
/// travels as an opaque id and is summed without being understood, which is all
/// a total requires.
public enum Nutrient {
    public static let protein = "protein"
    public static let fat = "fat"
    public static let carbohydrate = "carbohydrate"
    public static let alcohol = "alcohol"
    public static let fibre = "fibre"
    /// What the publisher reported, in kcal. Never overwritten with a computed
    /// figure — the two are different claims and `EnergyEstimate.basis` says
    /// which one a number came from.
    public static let energyKcal = "energy_kcal"
}

/// The general Atwater factors: 4/4/9/7 kcal per gram.
///
/// Used in preference to each publisher's own specific factors, and the reason
/// is comparability rather than accuracy. A day's log can mix USDA, CIQUAL,
/// CoFID and AFCD rows; those four apply different factor systems, so summing
/// their reported energies adds numbers that were not computed the same way.
/// Recomputing every food through one factor set makes the day's total mean
/// something. Where the macros are missing, `EnergyEstimate` falls back to what
/// the publisher reported and says so rather than returning a smaller number.
public enum GeneralAtwater {
    public static let proteinKcalPerGram = 4.0
    public static let carbohydrateKcalPerGram = 4.0
    public static let fatKcalPerGram = 9.0
    public static let alcoholKcalPerGram = 7.0

    public static func kcal(protein: Double, fat: Double,
                            carbohydrate: Double, alcohol: Double = 0) -> Double {
        protein * proteinKcalPerGram
            + fat * fatKcalPerGram
            + carbohydrate * carbohydrateKcalPerGram
            + alcohol * alcoholKcalPerGram
    }
}

public struct EnergyEstimate: Sendable, Hashable {
    public let kcal: Double
    public let basis: Basis

    public enum Basis: String, Sendable, Hashable, Codable {
        /// Computed from the macronutrients with the general factors.
        case generalAtwater = "general_atwater"
        /// The publisher's own energy figure, used because the macros needed
        /// to compute one were not analysed.
        case publisherReported = "publisher_reported"
    }

    public init(kcal: Double, basis: Basis) {
        self.kcal = kcal
        self.basis = basis
    }

    /// Energy per 100 g of edible portion, from that food's stored values.
    ///
    /// Nil when neither route is available — which is a different answer from
    /// zero, and the only honest one for a food nobody has analysed.
    public static func per100g(_ values: [NutrientValue]) -> EnergyEstimate? {
        func usable(_ id: String) -> Double? {
            guard let value = values.first(where: { $0.nutrientID == id }) else { return nil }
            switch value.qualifier {
            // Present but below the limit of quantification. Counting it as its
            // reported number would overstate; dropping the food would
            // understate. Zero is what "below the smallest measurable amount"
            // contributes to a day's energy.
            case .trace, .belowLOQ: return 0
            // Nobody measured it. Not zero, and not something to guess.
            case .notAnalysed: return nil
            default: return value.amount
            }
        }

        if let protein = usable(Nutrient.protein), let fat = usable(Nutrient.fat),
           let carbohydrate = usable(Nutrient.carbohydrate) {
            // A food with no alcohol row is taken as containing none. Every
            // composition database in groups A and B reports alcohol for the
            // items that carry it, so the absent case is "not an alcoholic
            // food" rather than "unmeasured".
            return EnergyEstimate(
                kcal: GeneralAtwater.kcal(protein: protein, fat: fat,
                                          carbohydrate: carbohydrate,
                                          alcohol: usable(Nutrient.alcohol) ?? 0),
                basis: .generalAtwater)
        }
        if let reported = usable(Nutrient.energyKcal) {
            return EnergyEstimate(kcal: reported, basis: .publisherReported)
        }
        return nil
    }

    /// Scales a per-100 g estimate to an actual mass.
    public func scaled(toGrams grams: Double) -> EnergyEstimate {
        EnergyEstimate(kcal: kcal * grams / 100, basis: basis)
    }
}

extension NutrientValue {
    /// This value scaled from its per-100 g basis to an actual mass.
    ///
    /// Nil for `notAnalysed`, which carries no number to scale. `trace` and
    /// `belowLOQ` scale to zero and keep their qualifier, so a total can still
    /// report that the food contributed something too small to count.
    public func scaled(toGrams grams: Double) -> Double? {
        switch qualifier {
        case .notAnalysed: return nil
        case .trace, .belowLOQ: return 0
        default: return amount.map { $0 * grams / 100 }
        }
    }
}

import Foundation

/// Migration 007 — the food log.
///
/// Appended; 001-006 are untouched.
///
/// The reference database answers "what is in this food". Nothing recorded
/// "the user ate 150 g of it". That is this table.
///
/// Two decisions worth the words:
///
/// 1. **`food_ref` is text, with no foreign key.** It holds a
///    `SourceIdentifier` — `usda:1105904`, `almanac:dish-kabsa`. Processing
///    Design v0.1 §3 keeps "remove a whole source" a one-line delete when a
///    rights holder says no; a foreign key with ON DELETE CASCADE would turn
///    that delete into the erasure of the user's own meal history. The log is
///    the user's record, not the publisher's, and it outlives the reference
///    rows it points at. `food_name_text` is what keeps an orphaned row
///    readable — the same reversibility discipline as
///    `NutrientValue.sourceValue` and `lab_observation.source_analyte_text`.
/// 2. **`grams` is nullable.** "Some rice, amount not stated" is a thing a
///    person logs, and NutrientQualifier already establishes that this
///    codebase does not write a number where nobody supplied one. An entry
///    with no amount yields no energy and says so, rather than yielding zero.
///
/// Energy is deliberately not a column here. It is a derivation from the
/// reference values and the grams, and storing it would freeze one answer to
/// a question whose inputs get corrected.
public enum Migration007_NutritionLog: Migration {
    public static let version = 7
    public static let name = "nutrition_log"

    public static func up(_ db: Database) throws {
        try db.execute("""
        CREATE TABLE nutrition_log (
            id                          TEXT    PRIMARY KEY,
            source_system               TEXT    NOT NULL,
            external_id                 TEXT,
            food_ref                    TEXT    NOT NULL,
            food_name_text              TEXT,
            grams                       REAL,
            quantity_text               TEXT,
            eaten_at                    TEXT,
            eaten_precision             TEXT    NOT NULL,
            eaten_tz_offset_minutes     INTEGER,
            eaten_tz_id                 TEXT,
            recorded_at                 TEXT    NOT NULL,
            recorded_tz_offset_minutes  INTEGER,
            deleted_at                  TEXT
        );
        """)

        // Identity is (source_system, external_id), as for health_sample: the
        // same string from a different source is a different meal. Manual
        // entries carry no external id and are therefore never deduplicated
        // against each other — eating the same food twice is not a replay.
        try db.execute("""
        CREATE UNIQUE INDEX idx_nutrition_log_source
            ON nutrition_log (source_system, external_id)
            WHERE external_id IS NOT NULL;
        """)
        try db.execute("CREATE INDEX idx_nutrition_log_time ON nutrition_log (eaten_at);")
        try db.execute("CREATE INDEX idx_nutrition_log_food ON nutrition_log (food_ref);")

        // One revision table, not two. A log entry is small enough that "what
        // was eaten" and "how much, when" are one fact; Laboratory splits them
        // only because a result's content and its metadata are revised by
        // different actors for different reasons.
        try db.execute("""
        CREATE TABLE nutrition_log_revision (
            id                      TEXT    PRIMARY KEY,
            log_id                  TEXT    NOT NULL
                                        REFERENCES nutrition_log(id) ON DELETE CASCADE,
            revision_number         INTEGER NOT NULL,
            food_ref                TEXT    NOT NULL,
            food_name_text          TEXT,
            grams                   REAL,
            quantity_text           TEXT,
            eaten_at                TEXT,
            eaten_precision         TEXT    NOT NULL,
            eaten_tz_offset_minutes INTEGER,
            eaten_tz_id             TEXT,
            changed_fields          TEXT    NOT NULL,
            actor                   TEXT    NOT NULL,
            reason_text             TEXT,
            recorded_at             TEXT    NOT NULL
        );
        """)
        try db.execute("""
        CREATE UNIQUE INDEX idx_nutrition_log_revision_number
            ON nutrition_log_revision (log_id, revision_number);
        """)
    }
}

import Foundation

// MARK: - Values

/// One ingredient of a dish, by weight.
public struct DishComponent: Sendable, Hashable {
    public let ref: SourceIdentifier
    public let grams: Double
    public let noteText: String?

    public init(_ ref: SourceIdentifier, grams: Double, noteText: String? = nil) {
        self.ref = ref
        self.grams = grams
        self.noteText = noteText
    }
}

/// What a recipe reduced to, and everything about it that is not known.
///
/// The three "not known" lists are separate because they have different fixes:
/// a missing component needs the reference row, an unmeasured nutrient cannot
/// be fixed at all, and a unit conflict is a canonicalisation bug upstream.
public struct RecipeReduction: Sendable, Hashable {
    /// Per 100 g of the finished dish, qualifier `.calculatedRecipe`.
    public let values: [NutrientValue]
    /// The finished weight the values are per-100-g of: the stated yield, or
    /// the sum of the components when no yield was given.
    public let totalGrams: Double
    /// The raw sum of component weights, before any cooking loss.
    public let componentGrams: Double
    /// Ingredients with no row in the catalog. Their contribution is not
    /// guessed, so every nutrient is affected and none of this is reliable.
    public let missingComponents: [SourceIdentifier]
    /// Nutrients at least one ingredient did not report, or reported as not
    /// analysed. A sum containing an unknown is unknown, so these are omitted
    /// from `values` rather than totalled as though the gap were zero.
    public let unmeasuredNutrients: [String]
    /// Nutrients whose ingredients disagree on the unit. Omitted rather than
    /// added together — the codebase converts no units anywhere else either.
    public let conflictingUnits: [String]

    public var isComplete: Bool {
        missingComponents.isEmpty && unmeasuredNutrients.isEmpty && conflictingUnits.isEmpty
    }
}

/// A correction to a dish's own fields. Component lists are replaced wholesale
/// by `setRecipe`, which is how a person edits a recipe anyway.
public struct DishEdit: Sendable, Hashable {
    public var nameText: FieldEdit<String> = .leaveUnchanged
    public var yieldGrams: FieldEdit<Double> = .leaveUnchanged
    public var edibleProportion: FieldEdit<Double> = .leaveUnchanged

    public init() {}

    public var touchesAnything: Bool {
        nameText.isChange || yieldGrams.isChange || edibleProportion.isChange
    }
}

// MARK: - Editor

/// Authoring for Almanac's own foods — the `almanac:` namespace, and only it.
///
/// A dish is reference data, not a record of the user's body, so it carries no
/// revision history: `lab_catalog_analyte` is upserted the same way for the
/// same reason, while `lab_observation` and `nutrition_log` — which *are*
/// records about a person — are revision-tracked. Adding dish revisions later
/// is an additive migration, not a redesign.
///
/// A publisher's row is never editable here. Correcting `usda:1105904` is
/// something USDA does; pretending otherwise would put an Almanac edit behind a
/// publisher's identifier and make the next import silently overwrite it.
public struct NutritionDishEditor: Sendable {
    private let db: Database
    private let clock: any Clock
    private let catalog: NutritionCatalog

    public init(db: Database, clock: any Clock = SystemClock()) {
        self.db = db
        self.clock = clock
        self.catalog = NutritionCatalog(db: db, clock: clock)
    }

    private static func requireNative(_ ref: SourceIdentifier) throws {
        guard ref.namespace == .almanac else { throw NutritionError.notANativeFood(ref) }
    }

    // MARK: Creating and editing the dish itself

    @discardableResult
    public func create(localID: String, nameText: String,
                       yieldGrams: Double? = nil,
                       edibleProportion: Double? = nil) throws -> SourceIdentifier {
        let ref = SourceIdentifier(namespace: .almanac, localID: localID)
        try catalog.upsert(NutritionFood(
            ref: ref, nameText: nameText, licenceGroup: ref.namespace.licenceGroup,
            edibleProportion: edibleProportion, yieldGrams: yieldGrams,
            sourceValue: nil))
        return ref
    }

    /// Per-100 g values typed in directly — a package label, or a figure the
    /// person knows. The alternative route is `setRecipe`.
    public func setValues(_ values: [NutrientValue], for ref: SourceIdentifier) throws {
        try NutritionDishEditor.requireNative(ref)
        try catalog.setValues(values, for: ref)
    }

    /// Applies a correction. Returns false when the edit changed nothing.
    ///
    /// A changed yield re-reduces the recipe, because the stored per-100 g
    /// values are per 100 g *of the finished dish* — leaving them alone would
    /// keep numbers that no longer describe anything.
    @discardableResult
    public func update(_ ref: SourceIdentifier, _ edit: DishEdit) throws -> Bool {
        try NutritionDishEditor.requireNative(ref)
        guard let held = try catalog.food(ref) else { throw NutritionError.foodNotFound(ref) }
        guard edit.touchesAnything else { return false }

        // A dish must be called something, so `.clear` on the name is a no-op
        // rather than an error case nobody would ever hit deliberately.
        let name = edit.nameText.resolve(held.nameText, cleared: held.nameText)
        let yield = edit.yieldGrams.resolve(held.yieldGrams)
        let edible = edit.edibleProportion.resolve(held.edibleProportion)
        guard name != held.nameText || yield != held.yieldGrams
                || edible != held.edibleProportion else { return false }

        try catalog.upsert(NutritionFood(
            ref: ref, nameText: name, licenceGroup: held.licenceGroup,
            edibleProportion: edible, yieldGrams: yield, sourceValue: held.sourceValue))
        if yield != held.yieldGrams, try !components(of: ref).isEmpty {
            _ = try reduceAndStore(ref)
        }
        return true
    }

    /// Removes the dish, its values and its components. A food log entry that
    /// pointed at it keeps its own row and its logged name — the log holds no
    /// foreign key here, exactly so that this delete cannot reach it.
    @discardableResult
    public func delete(_ ref: SourceIdentifier) throws -> Bool {
        try NutritionDishEditor.requireNative(ref)
        return try db.run("DELETE FROM nutrition_food WHERE food_ref = ?;",
                          [.text(ref.description)]) == 1
    }

    public func dishes() throws -> [NutritionFood] {
        try db.query("""
            SELECT food_ref, name_text, licence_group, edible_proportion, yield_grams, source_value
            FROM nutrition_food WHERE food_ref LIKE 'almanac:%' ORDER BY name_fold;
            """).compactMap(NutritionCatalog.food(from:))
    }

    // MARK: The recipe

    public func components(of ref: SourceIdentifier) throws -> [DishComponent] {
        try db.query("""
            SELECT component_ref, grams, note_text FROM nutrition_dish_component
            WHERE dish_ref = ? ORDER BY sequence;
            """, [.text(ref.description)]).compactMap { row in
            guard let componentRef = row.string("component_ref")
                    .flatMap(SourceIdentifier.init(parsing:)),
                  let grams = row.double("grams") else { return nil }
            return DishComponent(componentRef, grams: grams, noteText: row.string("note_text"))
        }
    }

    /// Replaces the recipe and recomputes the dish's per-100 g values from it.
    @discardableResult
    public func setRecipe(_ components: [DishComponent], for ref: SourceIdentifier,
                          yieldGrams: Double? = nil) throws -> RecipeReduction {
        try NutritionDishEditor.requireNative(ref)
        guard let held = try catalog.food(ref) else { throw NutritionError.foodNotFound(ref) }
        for component in components {
            guard component.grams.isFinite, component.grams > 0 else {
                throw NutritionError.invalidGramWeight(component.grams)
            }
            guard try !recipeReaches(ref, from: component.ref) else {
                throw NutritionError.recipeCycle(ref)
            }
        }

        // One transaction over all three writes. A recipe stored with the
        // values of the recipe before it is a dish whose numbers describe
        // nothing, and that is exactly what a failure between these steps used
        // to leave behind.
        return try db.transaction { () throws -> RecipeReduction in
            try db.run("DELETE FROM nutrition_dish_component WHERE dish_ref = ?;",
                       [.text(ref.description)])
            for (index, component) in components.enumerated() {
                try db.run("""
                INSERT INTO nutrition_dish_component
                    (id, dish_ref, component_ref, grams, sequence, note_text)
                VALUES (?, ?, ?, ?, ?, ?);
                """, [
                    .text(UUID().uuidString), .text(ref.description),
                    .text(component.ref.description), .real(component.grams),
                    .integer(Int64(index)),
                    component.noteText.map { SQLValue.text($0) } ?? .null
                ])
            }
            if let yieldGrams, yieldGrams != held.yieldGrams {
                // Written directly rather than through `update`, whose own
                // recompute would then run against the recipe twice.
                try catalog.upsert(NutritionFood(
                    ref: ref, nameText: held.nameText, licenceGroup: held.licenceGroup,
                    edibleProportion: held.edibleProportion, yieldGrams: yieldGrams,
                    sourceValue: held.sourceValue))
            }
            // Not `recompute`: emptying a recipe deliberately is allowed to
            // empty the values with it, which `recompute` refuses to do.
            return try reduceAndStore(ref)
        }
    }

    /// Whether `dish` already appears anywhere under `start`'s recipe.
    ///
    /// A dish may be an ingredient of another dish — that is the point of
    /// reducing to per-100 g values — but a loop is not stale data, it is two
    /// dishes each computed from the other's previous answer, and the reduction
    /// terminates on stored values so it would produce that number in silence.
    /// Walks the graph with a visited set rather than a depth limit, so a cycle
    /// already in the data cannot hang this.
    private func recipeReaches(_ dish: SourceIdentifier,
                               from start: SourceIdentifier) throws -> Bool {
        var queue = [start]
        var seen: Set<SourceIdentifier> = []
        while let next = queue.popLast() {
            guard seen.insert(next).inserted else { continue }
            if next == dish { return true }
            // Only Almanac's own foods have recipes; a publisher's row is a leaf.
            guard next.namespace == .almanac else { continue }
            queue.append(contentsOf: try components(of: next).map(\.ref))
        }
        return false
    }

    /// Re-reduces the stored recipe and writes the result.
    ///
    /// Explicit rather than automatic on read: a dish's values are stored so a
    /// day's total is one query, and recomputing them on every read would make
    /// a correction to an ingredient silently rewrite history instead of being
    /// an action someone took.
    @discardableResult
    public func recompute(_ ref: SourceIdentifier) throws -> RecipeReduction {
        try NutritionDishEditor.requireNative(ref)
        // A dish whose per-100 g values were typed in has nothing to reduce
        // from, and reducing an empty ingredient list yields an empty result —
        // so this would have quietly replaced what the person entered with
        // nothing. Refusing is the only answer that does not lose data.
        guard try !components(of: ref).isEmpty else {
            throw NutritionError.dishHasNoRecipe(ref)
        }
        return try reduceAndStore(ref)
    }

    /// The reduction and the write, with no guard. `recompute` is the public
    /// door and carries the guard; `setRecipe` comes in here because emptying a
    /// recipe on purpose is allowed to empty the values with it.
    @discardableResult
    private func reduceAndStore(_ ref: SourceIdentifier) throws -> RecipeReduction {
        guard let held = try catalog.food(ref) else { throw NutritionError.foodNotFound(ref) }
        let reduction = try reduce(try components(of: ref), yieldGrams: held.yieldGrams, as: ref)
        try catalog.setValues(reduction.values, for: ref)
        return reduction
    }

    /// The reduction itself, with no writing. Exposed so a person can see what
    /// a recipe comes to before committing it.
    public func reduce(_ components: [DishComponent], yieldGrams: Double? = nil,
                       as ref: SourceIdentifier = SourceIdentifier(namespace: .almanac,
                                                                   localID: "unsaved-recipe")
    ) throws -> RecipeReduction {
        let componentGrams = components.reduce(0) { $0 + $1.grams }
        let totalGrams = yieldGrams ?? componentGrams

        var missing: [SourceIdentifier] = []
        var loaded: [(component: DishComponent, values: [NutrientValue])] = []
        for component in components {
            guard try catalog.food(component.ref) != nil else {
                missing.append(component.ref)
                continue
            }
            loaded.append((component, try catalog.values(of: component.ref)))
        }

        func empty(_ missing: [SourceIdentifier]) -> RecipeReduction {
            RecipeReduction(values: [], totalGrams: totalGrams, componentGrams: componentGrams,
                            missingComponents: missing, unmeasuredNutrients: [],
                            conflictingUnits: [])
        }
        // An ingredient with no reference row contributes an unknown mass of
        // every nutrient. Totalling the rest would understate the dish across
        // the board, so nothing is computed and the gap is named instead.
        guard missing.isEmpty else { return empty(missing) }
        guard totalGrams > 0 else { return empty([]) }

        // Every nutrient any ingredient mentions. One that only some mention is
        // still unmeasured below — an ingredient that does not list iron has
        // not thereby reported zero iron.
        var nutrientIDs: [String] = []
        var seen: Set<String> = []
        for entry in loaded {
            for value in entry.values where !seen.contains(value.nutrientID) {
                seen.insert(value.nutrientID)
                nutrientIDs.append(value.nutrientID)
            }
        }

        var values: [NutrientValue] = []
        var unmeasured: [String] = []
        var conflicting: [String] = []

        for nutrientID in nutrientIDs.sorted() {
            var total = 0.0
            var unit: String?
            var unitConflict = false
            var complete = true

            for entry in loaded {
                guard let value = entry.values.first(where: { $0.nutrientID == nutrientID }),
                      let scaled = value.scaled(toGrams: entry.component.grams) else {
                    complete = false
                    break
                }
                // No unit is converted here, for the same reason `UnitRegistry`
                // converts none in Laboratory: a factor applied silently is a
                // wrong number nobody can see.
                if let unit, UnitRegistry.key(unit) != UnitRegistry.key(value.sourceUnit) {
                    unitConflict = true
                    break
                }
                unit = value.sourceUnit
                total += scaled
            }

            if unitConflict { conflicting.append(nutrientID); continue }
            guard complete else { unmeasured.append(nutrientID); continue }

            values.append(NutrientValue(
                foodRef: ref, nutrientID: nutrientID,
                amount: total / totalGrams * 100,
                qualifier: .calculatedRecipe,
                sourceValue: "sum of \(loaded.count) components over \(totalGrams) g",
                sourceNutrientID: nutrientID, sourceUnit: unit ?? "",
                licenceGroup: .permissive))
        }

        return RecipeReduction(values: values, totalGrams: totalGrams,
                               componentGrams: componentGrams, missingComponents: [],
                               unmeasuredNutrients: unmeasured, conflictingUnits: conflicting)
    }
}

import Foundation

// MARK: - Values

public enum NutritionLogError: Error, CustomStringConvertible, Sendable {
    case entryNotFound(String)
    case invalidGrams(Double)
    case foodRefRequired

    public var description: String {
        switch self {
        case .entryNotFound(let id):
            return "no food log entry with id '\(id)'."
        case .invalidGrams(let g):
            return "grams must be a finite amount greater than zero; got \(g). "
                 + "Leave it nil for 'amount not stated' — that is a different fact from zero."
        case .foodRefRequired:
            return "a log entry is always of some food; food_ref cannot be cleared, only set."
        }
    }
}

/// What a person (or an importer) says was eaten.
///
/// `grams` is optional on purpose: "some rice, amount not stated" is a real
/// entry, and writing 0 for it would claim the meal had no mass.
/// `quantityText` keeps what was actually typed — "2 cups", "one medium" —
/// so that a later portions table can re-derive the grams without asking the
/// user again, and so an entry made before that table exists is not lossy.
public struct NutritionLogDraft: Sendable, Hashable {
    public var sourceSystem: String
    /// The source's own id for this entry. Nil for a manual entry: two
    /// helpings of the same food are two meals, not a duplicate import.
    public var externalID: String?
    public var foodRef: SourceIdentifier
    /// What the food was called when it was logged. Survives the reference
    /// row being removed, which is the point.
    public var foodNameText: String?
    public var grams: Double?
    public var quantityText: String?
    public var eatenAt: PartialDateTime

    public init(foodRef: SourceIdentifier,
                grams: Double? = nil,
                eatenAt: PartialDateTime = .unknown,
                foodNameText: String? = nil,
                quantityText: String? = nil,
                sourceSystem: String = "manual",
                externalID: String? = nil) {
        self.foodRef = foodRef
        self.grams = grams
        self.eatenAt = eatenAt
        self.foodNameText = foodNameText
        self.quantityText = quantityText
        self.sourceSystem = sourceSystem
        self.externalID = externalID
    }
}

/// A correction to a log entry. Same three-case field semantics as
/// `LabObservationMetadataEdit`: leaving a field alone and emptying it are
/// different instructions, and an optional cannot say which was meant.
public struct NutritionLogEdit: Sendable, Hashable {
    public var foodRef: FieldEdit<SourceIdentifier> = .leaveUnchanged
    public var foodNameText: FieldEdit<String> = .leaveUnchanged
    public var grams: FieldEdit<Double> = .leaveUnchanged
    public var quantityText: FieldEdit<String> = .leaveUnchanged
    public var eatenAt: FieldEdit<PartialDateTime> = .leaveUnchanged

    public var actor: String = "user"
    public var reasonText: String? = nil

    public init() {}

    public var touchesAnything: Bool {
        foodRef.isChange || foodNameText.isChange || grams.isChange
            || quantityText.isChange || eatenAt.isChange
    }
}

public enum NutritionLogOutcome: Sendable, Hashable {
    case inserted(logID: String)
    case revised(logID: String, revisionID: String, revisionNumber: Int, changedFields: [String])
    case unchanged(logID: String)

    public var logID: String {
        switch self {
        case .inserted(let id), .unchanged(let id): return id
        case .revised(let id, _, _, _): return id
        }
    }
    public var changedFields: [String] {
        if case .revised(_, _, _, let fields) = self { return fields }
        return []
    }
}

/// A log entry as currently held.
public struct NutritionLogEntry: Sendable, Hashable {
    public let id: String
    public let sourceSystem: String
    public let externalID: String?
    public let foodRef: SourceIdentifier
    public let foodNameText: String?
    public let grams: Double?
    public let quantityText: String?
    public let eatenAt: PartialDateTime
    public let recordedAt: String
    public let deletedAt: String?

    public var isDeleted: Bool { deletedAt != nil }
}

/// A previous state of a log entry, with who changed it and why.
public struct NutritionLogRevision: Sendable, Hashable {
    public let id: String
    public let logID: String
    public let revisionNumber: Int
    public let foodRef: SourceIdentifier
    public let foodNameText: String?
    public let grams: Double?
    public let quantityText: String?
    public let eatenAt: PartialDateTime
    /// Which fields this revision is the *previous* value of.
    public let changedFields: [String]
    public let actor: String
    public let reasonText: String?
    public let recordedAt: String
}

// MARK: - Store

/// Persistence for the food log, and its timeline provider.
///
/// Holds what was eaten, not what it contained. Energy and nutrient totals are
/// a read-side join against the nutrition reference catalog: keeping them out
/// of here means a corrected reference value corrects every meal already
/// logged against it, instead of leaving thousands of frozen numbers behind.
public struct NutritionLogStore: TimelineProviding, @unchecked Sendable {
    public let domain = "nutrition"
    private let db: Database
    private let clock: any Clock
    private let zone: ZoneContext

    public init(db: Database, clock: any Clock = SystemClock(),
                zone: ZoneContext = ZoneContext(TimeZone.current)) {
        self.db = db
        self.clock = clock
        self.zone = zone
    }

    private var nowText: String { ISO8601DateFormatter().string(from: clock.now) }

    private static func validate(grams: Double?) throws {
        guard let g = grams else { return }
        guard g.isFinite, g > 0 else { throw NutritionLogError.invalidGrams(g) }
    }

    // MARK: Writing

    /// Records a meal, or revises the one this source already sent.
    ///
    /// An entry carrying an `externalID` is identified by
    /// `(source_system, external_id)`: re-importing it revises the held entry
    /// rather than adding a second meal, and revives it if the source had
    /// previously withdrawn it. A manual entry has no external id and is
    /// always a new meal.
    ///
    /// The outcome describes what happened to the entry's *values*, so a
    /// re-import that revives a withdrawn entry without changing anything comes
    /// back `.unchanged`. A caller that needs to know the entry is live again
    /// reads `entry(id:)`; treating `.unchanged` as "nothing happened" would
    /// miss the revival.
    @discardableResult
    public func record(_ draft: NutritionLogDraft) throws -> NutritionLogOutcome {
        try NutritionLogStore.validate(grams: draft.grams)
        return try db.transaction { () throws -> NutritionLogOutcome in
            if let externalID = draft.externalID,
               let held = try loadRow(sourceSystem: draft.sourceSystem, externalID: externalID) {
                var edit = NutritionLogEdit()
                edit.actor = draft.sourceSystem
                edit.foodRef = .set(draft.foodRef)
                edit.foodNameText = draft.foodNameText.map { FieldEdit<String>.set($0) } ?? .clear
                edit.grams = draft.grams.map { FieldEdit<Double>.set($0) } ?? .clear
                edit.quantityText = draft.quantityText.map { FieldEdit<String>.set($0) } ?? .clear
                edit.eatenAt = .set(draft.eatenAt)
                let outcome = try applyEdit(to: held, edit)
                // A source re-sending an entry it had withdrawn is asserting it
                // again. Matches HealthSampleStore's revival on re-arrival.
                if held.isDeleted {
                    try db.run("UPDATE nutrition_log SET deleted_at = NULL WHERE id = ?;",
                               [.text(held.id)])
                }
                return outcome
            }

            let id = UUID().uuidString
            try db.run("""
            INSERT INTO nutrition_log
                (id, source_system, external_id, food_ref, food_name_text, grams,
                 quantity_text, eaten_at, eaten_precision, eaten_tz_offset_minutes,
                 eaten_tz_id, recorded_at, recorded_tz_offset_minutes, deleted_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL);
            """, [
                .text(id), .text(draft.sourceSystem),
                draft.externalID.map { SQLValue.text($0) } ?? .null,
                .text(draft.foodRef.description),
                draft.foodNameText.map { SQLValue.text($0) } ?? .null,
                draft.grams.map { SQLValue.real($0) } ?? .null,
                draft.quantityText.map { SQLValue.text($0) } ?? .null,
                draft.eatenAt.isKnown ? .text(draft.eatenAt.text) : .null,
                .text(draft.eatenAt.precision.rawValue),
                draft.eatenAt.zone.offsetMinutes.map { SQLValue.integer(Int64($0)) } ?? .null,
                draft.eatenAt.zone.identifier.map { SQLValue.text($0) } ?? .null,
                .text(nowText),
                zone.offsetMinutes.map { SQLValue.integer(Int64($0)) } ?? .null
            ])
            return .inserted(logID: id)
        }
    }

    /// Corrects a held entry. Previous values move to
    /// `nutrition_log_revision` with the actor, the reason, and the list of
    /// fields touched — never an unrecorded in-place overwrite.
    @discardableResult
    public func update(id logID: String, _ edit: NutritionLogEdit) throws -> NutritionLogOutcome {
        if case .clear = edit.foodRef { throw NutritionLogError.foodRefRequired }
        guard let held = try loadRow(id: logID) else {
            throw NutritionLogError.entryNotFound(logID)
        }
        guard edit.touchesAnything else { return .unchanged(logID: logID) }
        return try db.transaction { try applyEdit(to: held, edit) }
    }

    /// Soft delete. The entry stops counting and stops appearing on the
    /// timeline; it is not erased, so a mistaken delete is recoverable and an
    /// importer re-asserting the entry revives it.
    @discardableResult
    public func delete(id logID: String) throws -> Bool {
        try db.run("""
            UPDATE nutrition_log SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL;
            """, [.text(nowText), .text(logID)]) == 1
    }

    /// Writes the revision and the new row. Caller owns the transaction.
    private func applyEdit(to held: NutritionLogEntry,
                           _ edit: NutritionLogEdit) throws -> NutritionLogOutcome {
        let foodRef = edit.foodRef.resolve(held.foodRef, cleared: held.foodRef)
        let foodNameText = edit.foodNameText.resolve(held.foodNameText)
        let grams = edit.grams.resolve(held.grams)
        let quantityText = edit.quantityText.resolve(held.quantityText)
        let eatenAt = edit.eatenAt.resolve(held.eatenAt, cleared: .unknown)
        try NutritionLogStore.validate(grams: grams)

        var changed: [String] = []
        if foodRef != held.foodRef { changed.append("food_ref") }
        if foodNameText != held.foodNameText { changed.append("food_name_text") }
        if grams != held.grams { changed.append("grams") }
        if quantityText != held.quantityText { changed.append("quantity_text") }
        if eatenAt != held.eatenAt { changed.append("eaten_at") }
        guard !changed.isEmpty else { return .unchanged(logID: held.id) }

        let next = Int(try db.query("""
            SELECT COALESCE(MAX(revision_number), 0) AS n
            FROM nutrition_log_revision WHERE log_id = ?;
            """, [.text(held.id)]).first?.int("n") ?? 0) + 1
        let revisionID = UUID().uuidString
        try db.run("""
        INSERT INTO nutrition_log_revision
            (id, log_id, revision_number, food_ref, food_name_text, grams, quantity_text,
             eaten_at, eaten_precision, eaten_tz_offset_minutes, eaten_tz_id,
             changed_fields, actor, reason_text, recorded_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
        """, [
            .text(revisionID), .text(held.id), .integer(Int64(next)),
            .text(held.foodRef.description),
            held.foodNameText.map { SQLValue.text($0) } ?? .null,
            held.grams.map { SQLValue.real($0) } ?? .null,
            held.quantityText.map { SQLValue.text($0) } ?? .null,
            held.eatenAt.isKnown ? .text(held.eatenAt.text) : .null,
            .text(held.eatenAt.precision.rawValue),
            held.eatenAt.zone.offsetMinutes.map { SQLValue.integer(Int64($0)) } ?? .null,
            held.eatenAt.zone.identifier.map { SQLValue.text($0) } ?? .null,
            .text(changed.joined(separator: ",")), .text(edit.actor),
            edit.reasonText.map { SQLValue.text($0) } ?? .null, .text(nowText)
        ])

        try db.run("""
        UPDATE nutrition_log SET
            food_ref = ?, food_name_text = ?, grams = ?, quantity_text = ?,
            eaten_at = ?, eaten_precision = ?, eaten_tz_offset_minutes = ?, eaten_tz_id = ?
        WHERE id = ?;
        """, [
            .text(foodRef.description),
            foodNameText.map { SQLValue.text($0) } ?? .null,
            grams.map { SQLValue.real($0) } ?? .null,
            quantityText.map { SQLValue.text($0) } ?? .null,
            eatenAt.isKnown ? .text(eatenAt.text) : .null,
            .text(eatenAt.precision.rawValue),
            eatenAt.zone.offsetMinutes.map { SQLValue.integer(Int64($0)) } ?? .null,
            eatenAt.zone.identifier.map { SQLValue.text($0) } ?? .null,
            .text(held.id)
        ])
        return .revised(logID: held.id, revisionID: revisionID,
                        revisionNumber: next, changedFields: changed)
    }

    // MARK: Reading

    private static let columns = """
        id, source_system, external_id, food_ref, food_name_text, grams, quantity_text,
        eaten_at, eaten_precision, eaten_tz_offset_minutes, eaten_tz_id,
        recorded_at, deleted_at
        """

    public func entry(id logID: String) throws -> NutritionLogEntry? {
        try loadRow(id: logID)
    }

    private func loadRow(id logID: String) throws -> NutritionLogEntry? {
        try db.query("SELECT \(NutritionLogStore.columns) FROM nutrition_log WHERE id = ?;",
                     [.text(logID)]).first.flatMap(NutritionLogStore.entry(from:))
    }

    private func loadRow(sourceSystem: String, externalID: String) throws -> NutritionLogEntry? {
        try db.query("""
            SELECT \(NutritionLogStore.columns) FROM nutrition_log
            WHERE source_system = ? AND external_id = ?;
            """, [.text(sourceSystem), .text(externalID)])
            .first.flatMap(NutritionLogStore.entry(from:))
    }

    public func revisions(of logID: String) throws -> [NutritionLogRevision] {
        try db.query("""
            SELECT id, log_id, revision_number, food_ref, food_name_text, grams,
                   quantity_text, eaten_at, eaten_precision, eaten_tz_offset_minutes,
                   eaten_tz_id, changed_fields, actor, reason_text, recorded_at
            FROM nutrition_log_revision WHERE log_id = ? ORDER BY revision_number;
            """, [.text(logID)]).compactMap { row in
            guard let id = row.string("id"), let rowLogID = row.string("log_id"),
                  let ref = row.string("food_ref").flatMap(SourceIdentifier.init(parsing:)),
                  let eaten = NutritionLogStore.eatenAt(row) else { return nil }
            return NutritionLogRevision(
                id: id, logID: rowLogID,
                revisionNumber: Int(row.int("revision_number") ?? 0),
                foodRef: ref, foodNameText: row.string("food_name_text"),
                grams: row.double("grams"), quantityText: row.string("quantity_text"),
                eatenAt: eaten,
                changedFields: (row.string("changed_fields") ?? "")
                    .split(separator: ",").map(String.init),
                actor: row.string("actor") ?? "", reasonText: row.string("reason_text"),
                recordedAt: row.string("recorded_at") ?? "")
        }
    }

    private static func eatenAt(_ row: Row) -> PartialDateTime? {
        PartialDateTime(
            storedText: row.string("eaten_at") ?? "",
            precision: TimePrecision(rawValue: row.string("eaten_precision") ?? "") ?? .unknown,
            zone: ZoneContext(offsetMinutes: row.int("eaten_tz_offset_minutes").map(Int.init),
                              identifier: row.string("eaten_tz_id")))
    }

    private static func entry(from row: Row) -> NutritionLogEntry? {
        guard let id = row.string("id"),
              let ref = row.string("food_ref").flatMap(SourceIdentifier.init(parsing:)),
              let eaten = eatenAt(row) else { return nil }
        return NutritionLogEntry(
            id: id, sourceSystem: row.string("source_system") ?? "",
            externalID: row.string("external_id"), foodRef: ref,
            foodNameText: row.string("food_name_text"), grams: row.double("grams"),
            quantityText: row.string("quantity_text"), eatenAt: eaten,
            recordedAt: row.string("recorded_at") ?? "",
            deletedAt: row.string("deleted_at"))
    }

    /// Live entries placed in `[from, to)`, with their placement.
    ///
    /// The domain-value counterpart of `entries(from:to:)`: the timeline gets
    /// presentation, a totals or day screen gets the grams and the food ref it
    /// needs to join on. Both go through `placed` so the two can never disagree
    /// about which meals fall in a range.
    public func logged(from: String, to: String) throws -> [PlacedLogEntry] {
        guard let range = DateRange(from: from, to: to) else { return [] }
        return try liveRows().compactMap { NutritionLogStore.placed($0, in: range) }
    }

    /// A log entry with the time the timeline would place it at.
    public struct PlacedLogEntry: Sendable, Hashable {
        public let entry: NutritionLogEntry
        public let occurrence: PartialDateTime
        public let basis: TimeBasis
        public let rangeFit: RangeFit
    }

    private func liveRows() throws -> [Row] {
        try db.query("""
            SELECT \(NutritionLogStore.columns) FROM nutrition_log
            WHERE deleted_at IS NULL;
            """)
    }

    /// Placement is the eaten time, else when it was recorded. There is no
    /// `reported` basis: a meal has no report, and falling back to
    /// `recorded_at` is the same weaker claim Laboratory marks that way.
    /// Nil when the entry cannot belong to the range at all.
    private static func placed(_ row: Row, in range: DateRange) -> PlacedLogEntry? {
        guard let held = entry(from: row) else { return nil }
        let occurrence: PartialDateTime
        let basis: TimeBasis
        if held.eatenAt.isKnown {
            occurrence = held.eatenAt
            basis = .occurrence
        } else if let recorded = PartialDateTime(storedText: held.recordedAt,
                                                 precision: .instant) {
            occurrence = recorded
            basis = .recorded
        } else {
            return nil
        }
        guard let fit = occurrence.fit(in: range) else { return nil }
        return PlacedLogEntry(entry: held, occurrence: occurrence, basis: basis, rangeFit: fit)
    }

    // MARK: - TimelineProviding

    public func entries(from: String, to: String) throws -> [TimelineEntry] {
        guard let range = DateRange(from: from, to: to) else { return [] }
        return try liveRows().compactMap { row in
            guard let placed = NutritionLogStore.placed(row, in: range) else { return nil }
            let held = placed.entry

            let value: ValuePresentation
            if let grams = held.grams {
                value = .quantity(text: String(grams), unit: "g")
            } else {
                // Not zero. Nobody said how much, which is a different fact —
                // the same distinction NutrientQualifier draws for nutrients.
                value = .missing(reason: "amount not stated")
            }
            return TimelineEntry(
                domain: domain, kind: "food", recordTable: "nutrition_log",
                recordID: held.id, occurrence: placed.occurrence, basis: placed.basis,
                title: held.foodNameText ?? held.foodRef.description,
                detail: held.quantityText, value: value, lifecycle: nil,
                rangeFit: placed.rangeFit)
        }
    }
}

import Foundation

/// One logged meal, joined to what the catalog knows about it.
public struct LoggedFood: Sendable, Hashable {
    public let entry: NutritionLogEntry
    public let occurrence: PartialDateTime
    public let basis: TimeBasis
    /// Nil when the reference row is gone — a source was removed, or the entry
    /// was logged against a food that never existed. `entry.foodNameText` is
    /// what the person saw at the time and is still readable.
    public let food: NutritionFood?
    /// Scaled to the logged mass. Nil when neither the macros nor a published
    /// energy figure were available, which is not the same as no calories.
    public let energy: EnergyEstimate?
}

/// What a range of the food log adds up to, and what it could not add up.
///
/// Every "could not" is a separate field rather than a silent omission. A
/// calorie total that quietly drops the meals it could not price is the single
/// most misleading number this module could produce.
public struct NutritionTotals: Sendable, Hashable {
    public let kcal: Double
    /// Which routes the energy came through. More than one entry means the
    /// total mixes computed and publisher-reported figures, which a UI should
    /// be able to say.
    public let energyBases: Set<EnergyEstimate.Basis>
    /// Per nutrient id, summed over the counted meals. A nutrient that any
    /// counted meal could not supply is **absent from this dictionary** and
    /// named in `incompleteNutrients` — never present as a smaller number.
    public let nutrients: [String: Double]
    public let mealsCounted: Int
    /// Logged, but with no amount stated, so they contribute nothing.
    public let mealsWithoutAmount: [String]
    /// Logged against a food the catalog does not hold.
    public let mealsWithoutReference: [SourceIdentifier]
    /// Nutrients at least one counted meal did not report, reported as not
    /// analysed, or reported in a unit that disagrees with another meal's.
    public let incompleteNutrients: [String]

    public var isComplete: Bool {
        mealsWithoutAmount.isEmpty && mealsWithoutReference.isEmpty
            && incompleteNutrients.isEmpty
    }
}

/// Reads the food log against the reference catalog.
///
/// Holds nothing and stores nothing: totals are derived on demand, so a
/// corrected reference value corrects every day already logged against it. That
/// is the whole reason `nutrition_log` carries no energy column.
public struct NutritionSummary: Sendable {
    private let log: NutritionLogStore
    private let catalog: NutritionCatalog

    public init(db: Database, clock: any Clock = SystemClock(),
                zone: ZoneContext = ZoneContext(TimeZone.current)) {
        self.log = NutritionLogStore(db: db, clock: clock, zone: zone)
        self.catalog = NutritionCatalog(db: db, clock: clock)
    }

    public func loggedFoods(from: String, to: String) throws -> [LoggedFood] {
        let cache = Cache(catalog)
        return try log.logged(from: from, to: to).map { placed in
            let ref = placed.entry.foodRef
            let food = try cache.food(ref)
            var energy: EnergyEstimate?
            if food != nil, let grams = placed.entry.grams {
                energy = EnergyEstimate.per100g(try cache.values(ref))?.scaled(toGrams: grams)
            }
            return LoggedFood(entry: placed.entry, occurrence: placed.occurrence,
                              basis: placed.basis, food: food, energy: energy)
        }
    }

    /// A day of the same rice is one lookup, not one per helping. Scoped to a
    /// single call, so nothing here goes stale between them.
    private final class Cache {
        private let catalog: NutritionCatalog
        private var foodCache: [SourceIdentifier: NutritionFood?] = [:]
        private var valueCache: [SourceIdentifier: [NutrientValue]] = [:]
        init(_ catalog: NutritionCatalog) { self.catalog = catalog }

        func food(_ ref: SourceIdentifier) throws -> NutritionFood? {
            if let hit = foodCache[ref] { return hit }
            let loaded = try catalog.food(ref)
            foodCache[ref] = loaded
            return loaded
        }

        func values(_ ref: SourceIdentifier) throws -> [NutrientValue] {
            if let hit = valueCache[ref] { return hit }
            let loaded = try catalog.values(of: ref)
            valueCache[ref] = loaded
            return loaded
        }
    }

    /// The same reads, for a logical day rather than a pair of ISO strings.
    ///
    /// "What did I eat today" is not a UTC range: a day in Riyadh starts at
    /// 21:00Z the evening before, and a body monitor's day may not start at
    /// midnight at all. Both questions go through `TimeModel`, which is where
    /// the boundary rule lives — so when `.midnight` stops being the
    /// placeholder `DayBoundary` says it is, every total moves with it instead
    /// of needing to be found and changed here.
    ///
    /// Nil when the model cannot place the day, which is what it returns for a
    /// date that does not exist.
    public func totals(on day: LogicalDay, in model: TimeModel) throws -> NutritionTotals? {
        guard let bounds = NutritionSummary.textBounds(day, model) else { return nil }
        return try totals(from: bounds.start, to: bounds.end)
    }

    public func loggedFoods(on day: LogicalDay, in model: TimeModel) throws -> [LoggedFood]? {
        guard let bounds = NutritionSummary.textBounds(day, model) else { return nil }
        return try loggedFoods(from: bounds.start, to: bounds.end)
    }

    /// Normalised to UTC text before it reaches the range reads, the same way
    /// `HealthSampleStore` normalises its query bounds — comparing a stored
    /// `...Z` value against a caller's `+03:00` text is wrong by the offset,
    /// and silently so.
    private static func textBounds(_ day: LogicalDay,
                                   _ model: TimeModel) -> (start: String, end: String)? {
        guard let bounds = model.bounds(of: day) else { return nil }
        return DateRange(start: bounds.start, end: bounds.end).utcTextBounds
    }

    public func totals(from: String, to: String) throws -> NutritionTotals {
        let cache = Cache(catalog)
        var counted: [(ref: SourceIdentifier, grams: Double)] = []
        var withoutAmount: [String] = []
        var withoutReference: [SourceIdentifier] = []
        var incomplete: Set<String> = []
        var kcal = 0.0
        var bases: Set<EnergyEstimate.Basis> = []

        for placed in try log.logged(from: from, to: to) {
            let entry = placed.entry
            guard let grams = entry.grams else {
                withoutAmount.append(entry.id)
                continue
            }
            guard try cache.food(entry.foodRef) != nil else {
                withoutReference.append(entry.foodRef)
                continue
            }
            counted.append((entry.foodRef, grams))

            if let energy = EnergyEstimate.per100g(try cache.values(entry.foodRef))?
                .scaled(toGrams: grams) {
                kcal += energy.kcal
                bases.insert(energy.basis)
            } else {
                // This meal contributed calories nobody can put a number on, so
                // the running total understates and must say so.
                incomplete.insert(Nutrient.energyKcal)
            }
        }

        var nutrientIDs: Set<String> = []
        for (ref, _) in counted {
            nutrientIDs.formUnion(try cache.values(ref).map(\.nutrientID))
        }

        var totals: [String: Double] = [:]
        for nutrientID in nutrientIDs {
            var sum = 0.0
            var unit: String?
            var usable = true
            for (ref, grams) in counted {
                guard let value = try cache.values(ref)
                        .first(where: { $0.nutrientID == nutrientID }),
                      let scaled = value.scaled(toGrams: grams) else {
                    usable = false
                    break
                }
                // Nothing here converts units, so two meals reporting a
                // nutrient on different scales are not added together.
                if let unit, UnitRegistry.key(unit) != UnitRegistry.key(value.sourceUnit) {
                    usable = false
                    break
                }
                unit = value.sourceUnit
                sum += scaled
            }
            if usable { totals[nutrientID] = sum } else { incomplete.insert(nutrientID) }
        }

        return NutritionTotals(
            kcal: kcal, energyBases: bases, nutrients: totals, mealsCounted: counted.count,
            mealsWithoutAmount: withoutAmount, mealsWithoutReference: withoutReference,
            incompleteNutrients: incomplete.sorted())
    }
}

import Foundation

/// Processing Design v0.1 §3 — namespace, never renumber.
///
/// `usda:1105904`, `ciqual:1000`, `cofid:13-145`, `afcd:F002258`.
/// An Almanac-internal integer key is a private detail that must never replace
/// the publisher's identifier. Namespacing keeps a food traceable to its
/// publisher, lets two sources sit side by side, and — the point that matters —
/// keeps "remove a whole source" a one-line delete when a rights holder says no.
public struct SourceIdentifier: Codable, Sendable, Hashable, CustomStringConvertible {
    public let namespace: Namespace
    public let localID: String

    public enum Namespace: String, Codable, Sendable, CaseIterable, Hashable {
        case usda, ciqual, cofid, afcd, frida
        case openFoodFacts = "off"
        case sfda, wger, freeExerciseDB = "fedb", everkinetic, opentraining
        /// Rows Almanac owns outright. The only namespace Almanac may license
        /// independently.
        case almanac

        public var licenceGroup: LicenceGroup {
            switch self {
            case .usda: return .permissive
            case .almanac: return .native
            case .ciqual, .cofid, .afcd, .frida: return .attribution
            case .openFoodFacts: return .shareAlike
            case .sfda: return .restricted
            // Exercise sources carry per-entry licences (wger admits ODbL as a
            // possible value). They are never classified at source level —
            // exercise rows must carry their own group column.
            case .wger, .freeExerciseDB, .everkinetic, .opentraining: return .restricted
            }
        }
    }

    public init(namespace: Namespace, localID: String) {
        self.namespace = namespace
        self.localID = localID
    }

    public var description: String { "\(namespace.rawValue):\(localID)" }

    public init?(parsing text: String) {
        guard let sep = text.firstIndex(of: ":") else { return nil }
        let ns = String(text[text.startIndex..<sep])
        let rest = String(text[text.index(after: sep)...])
        guard let namespace = Namespace(rawValue: ns), !rest.isEmpty else { return nil }
        self.init(namespace: namespace, localID: rest)
    }
}

