3	/// A calorie figure and how it was reached. Always `calculatedFactor`: energy
4	/// in a food table is computed from components, never measured.
5	public struct EnergyEstimate: Sendable, Hashable {
6	    public enum Method: String, Sendable, Hashable {
7	        /// Almanac's own figure: 4/4/9/7 kcal per gram (handoff 2026-09-13).
8	        case generalAtwater = "general_atwater"
9	        /// The publisher's own energy value, made with the publisher's own factors.
10	        /// Used only when general Atwater cannot be computed; not comparable across
11	        /// publishers, so it is always labelled.
12	        case publisherReported = "publisher_reported"
13	    }
14	
15	    /// General Atwater applies 4 kcal/g to *total* carbohydrate. Sources publish
16	    /// different quantities under "carbohydrate", so the term records which one
17	    /// was made total, and how (tools/nutrition/README.md, "Carbohydrate").
18	    public enum CarbohydrateTerm: String, Sendable, Hashable {
19	        /// Total carbohydrate by difference, fibre included (USDA).
20	        case byDifference = "by_difference"
21	        /// Available carbohydrate by weight plus total dietary fibre (CIQUAL, AFCD).
22	        case availablePlusFibre = "available_plus_fibre"
23	        /// Available carbohydrate as monosaccharide equivalents plus fibre (CoFID).
24	        case availableMonosaccharidePlusFibre = "available_monosaccharide_plus_fibre"
25	    }
26	
27	    public let kilocalories: Double
28	    public let basis: NutritionBasis
29	    public let method: Method
30	    public let carbohydrateTerm: CarbohydrateTerm?
31	    /// Canonical nutrients that entered the sum as zero although the source did not
32	    /// report zero: traces, "< x" bounds, and absent or unanalysed alcohol. Sorted.
33	    public let inputsTakenAsZero: [String]
34	
35	    public var qualifier: NutrientQualifier { .calculatedFactor }
36	
37	    /// Almanac's calorie number for a food on one basis: general Atwater when it can
38	    /// be computed, else the publisher's own figure, else nil. A trace, an unanalysed
39	    /// value or a "< x" bound is never shown as a calorie figure.
40	    public static func preferred(from values: [NutrientValue], basis: NutritionBasis) -> EnergyEstimate? {
41	        if let atwater = GeneralAtwater.estimate(from: values, basis: basis) { return atwater }
42	        guard let published = values.first(where: { $0.basis == basis && $0.nutrientID == "energy_kcal" }),
43	              published.qualifier != .belowLOQ,
44	              let kilocalories = published.amount else { return nil }
45	        return EnergyEstimate(kilocalories: kilocalories, basis: basis, method: .publisherReported,
46	                              carbohydrateTerm: nil, inputsTakenAsZero: [])
47	    }
48	}
49	
50	/// General Atwater factors. Per-food specific factors are a v2 refinement.
51	public enum GeneralAtwater {
52	    public static let proteinKilocaloriesPerGram = 4.0
53	    public static let carbohydrateKilocaloriesPerGram = 4.0
54	    public static let fatKilocaloriesPerGram = 9.0
55	    public static let alcoholKilocaloriesPerGram = 7.0
56	
57	    /// nil when protein, fat or total carbohydrate cannot be read — never a guess.
58	    public static func estimate(from values: [NutrientValue], basis: NutritionBasis) -> EnergyEstimate? {
59	        var published: [String: NutrientValue] = [:]
60	        for value in values where value.basis == basis { published[value.nutrientID] = value }
61	        let read = { (nutrient: String) in Term(published[nutrient]) }
62	
63	        guard let protein = read("protein"), let fat = read("fat_total"),
64	              let carbohydrate = totalCarbohydrate(read) else { return nil }
65	        // Every source's own energy figure counts alcohol only where it is present.
66	        let alcohol = read("alcohol") ?? Term(grams: 0, takenAsZero: ["alcohol"])
67	
68	        let kilocalories = proteinKilocaloriesPerGram * protein.grams
69	            + carbohydrateKilocaloriesPerGram * carbohydrate.total.grams
70	            + fatKilocaloriesPerGram * fat.grams
71	            + alcoholKilocaloriesPerGram * alcohol.grams
72	        let zeros = protein.takenAsZero + fat.takenAsZero + carbohydrate.total.takenAsZero + alcohol.takenAsZero
73	        return EnergyEstimate(kilocalories: kilocalories, basis: basis, method: .generalAtwater,
74	                              carbohydrateTerm: carbohydrate.term, inputsTakenAsZero: zeros.sorted())
75	    }
76	
77	    /// By difference if published; otherwise available carbohydrate plus fibre.
78	    /// Fibre is never assumed, so available carbohydrate alone gives no total.
79	    private static func totalCarbohydrate(_ read: (String) -> Term?)
80	        -> (total: Term, term: EnergyEstimate.CarbohydrateTerm)? {
81	        if let total = read("carbohydrate_by_difference") { return (total, .byDifference) }
82	        guard let fibre = read("fibre_total_dietary") else { return nil }
83	        if let available = read("carbohydrate_available") {
84	            return (available + fibre, .availablePlusFibre)
85	        }
86	        if let available = read("carbohydrate_available_monosaccharide") {
87	            return (available + fibre, .availableMonosaccharidePlusFibre)
88	        }
89	        return nil
90	    }
91	
92	    /// Grams entering the sum, and which nutrients entered it as zero without the
93	    /// source saying zero.
94	    private struct Term {
95	        let grams: Double
