                id: id, logID: rowLogID,
                revisionNumber: Int(row.int("revision_number") ?? 0),
                foodRef: ref, foodNameText: row.string("food_name_text"),
                grams: row.double("grams"), quantityText: row.string("quantity_text"),
                eatenAt: eaten,
