        try seedOneFood(db)
        for (index, qualifier) in NutrientQualifier.allCases.enumerated() {
            let ref = "cofid:q\(index)"
            try db.execute("""
            INSERT INTO nutrition_food (food_ref, namespace, local_id, licence_group, food_group_code,
